parameters.jsCode:
const body = $input.first().json.body;

const required = ['tenant_name', 'unit', 'description'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

return [{
  json: {
    valid: true,
    ticketId: `MR-${Date.now()}`,
    tenantName: body.tenant_name.trim(),
    tenantEmail: body.tenant_email || null,
    tenantPhone: body.tenant_phone || null,
    unit: body.unit.trim(),
    building: body.building || $env.DEFAULT_BUILDING || 'Main Building',
    description: body.description.trim().slice(0, 1500),
    category: body.category || null,
    photoUrls: Array.isArray(body.photo_urls) ? body.photo_urls.slice(0, 4) : [],
    preferredTimeSlot: body.preferred_time_slot || 'any',
    entryPermission: body.entry_permission !== false,
    submittedAt: new Date().toISOString()
  }
}];

values.content:
Triage this maintenance request.

Unit: {{ $json.unit }}
Building: {{ $json.building }}
Tenant-provided category (may be blank): {{ $json.category || 'not specified' }}
Description: {{ $json.description }}
Entry permission granted: {{ $json.entryPermission }}
Preferred time: {{ $json.preferredTimeSlot }}

Return this JSON:
{
  "category": "one of: plumbing | electrical | hvac | appliance | structural | pest | locksmith | cleaning | general_repair | landscaping | other",
  "urgency": "one of: emergency | high | medium | low",
  "urgency_reason": "one sentence explaining why this urgency level",
  "safety_risk": true or false,
  "safety_detail": "if safety_risk is true, describe the specific risk in one sentence. null otherwise.",
  "assigned_trade": "who should handle this: plumber | electrician | hvac_tech | handyman | pest_control | locksmith | building_manager | cleaning_crew | contractor",
  "estimated_scope": "one of: minor_repair | moderate_repair | major_repair | replacement | investigation_needed",
  "tenant_acknowledgement": "a brief, warm message to send the tenant (2-3 sentences). Confirm receipt, state the urgency level and what happens next, give ticket ID {{ $json.ticketId }}. Don't overpromise timelines unless you're certain.",
  "internal_notes": "what the assigned trade should know before arriving — anything specific from the description that affects diagnosis or preparation, under 80 words.",
  "suggested_questions": ["any clarifying questions the manager might want to ask the tenant before dispatching, if the description is ambiguous. Empty array if clear enough."]
}

parameters.jsCode:
const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let triage;
try {
  triage = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Triage parse failed', raw } }];
}

const req = $('Validate & Enrich').first().json;

return [{
  json: {
    ...triage,
    ticketId: req.ticketId,
    tenantName: req.tenantName,
    tenantEmail: req.tenantEmail,
    tenantPhone: req.tenantPhone,
    unit: req.unit,
    building: req.building,
    description: req.description,
    preferredTimeSlot: req.preferredTimeSlot,
    entryPermission: req.entryPermission,
    photoUrls: req.photoUrls,
    submittedAt: req.submittedAt
  }
}];
